def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


from bisect import bisect_right


def minEditsToBst(tree):
    vals, left, right = _links(tree)
    if not vals:
        return 0
    order = []
    stack = []
    x = 0
    while stack or x != -1:
        while x != -1:
            stack.append(x)
            x = left[x]
        x = stack.pop()
        order.append(vals[x])
        x = right[x]
    tails = []
    for i, v in enumerate(order):
        b = v - i
        j = bisect_right(tails, b)
        if j == len(tails):
            tails.append(b)
        else:
            tails[j] = b
    return len(order) - len(tails)
